 static bool Protected(Vector3 p){foreach(var r in roads){r.Project(p,out float d);if(d<3.8f)return true;}return false;}
 static Material Mat(string n,Color c){string path=F+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=n,color=c};AssetDatabase.CreateAsset(m,path);}return m;}
