 static GameObject MeshPart(string n,List<Vector3> v,List<int> t,Material mat,bool collision=true){var m=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};m.SetVertices(v);m.SetTriangles(t,0);m.uv=v.Select(p=>new Vector2(p.x,p.z)*.18f).ToArray();m=Store(m,n);var g=new GameObject(n,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(root);g.GetComponent<MeshFilter>().sharedMesh=m;g.GetComponent<Renderer>().sharedMaterial=mat;if(collision)g.AddComponent<MeshCollider>().sharedMesh=m;return g;}
