 static Vector3[] Curve(Vector3[] k){var p=new List<Vector3>();for(int i=0;i<k.Length-1;i++){var a=k[Math.Max(0,i-1)];var b=k[i];var c=k[i+1];var d=k[Math.Min(k.Length-1,i+2)];int n=Mathf.CeilToInt(Vector3.Distance(b,c)/.5f);for(int j=0;j<n;j++){float t=j/(float)n;p.Add(.5f*(2*b+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t));}}p.Add(k[^1]);return p.ToArray();}
 static void Reset(WoodlandRoute b){typeof(WoodlandRoute).GetField("lengths",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(b,null);b.Initialize();}
