 public static string Main(){if(Application.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit mode required");Directory.CreateDirectory(F);Directory.CreateDirectory(D);AssetDatabase.Refresh();notes.Clear();serial=0;
 foreach(string scene in new[]{"DansBackyardReverse","DansBackyardForward"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");var prior=GameObject.Find("Reverse optional forest shortcuts");var oldRidge=prior.GetComponentsInChildren<WoodlandRoute>().FirstOrDefault(b=>b.title.StartsWith("Abandoned"));Vector3[] old=oldRidge?oldRidge.points.ToArray():Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText("Docs/ReverseShortcuts/geometry.json"))["branches"].First(b=>(string)b["title"]=="Abandoned Logging Ridge")["points"].Select(p=>new Vector3((float)p["x"],(float)p["y"],(float)p["z"])).ToArray();Object.DestroyImmediate(prior);
 // Restore only the obsolete shortcut's portal cuts from their recorded source meshes.
