 root=new GameObject("Reverse optional forest shortcuts").transform;race=Object.FindAnyObjectByType<RaceDirector>();roads=Object.FindObjectsByType<RaceRoad>();Physics.SyncTransforms();earth=Mat("Weathered logging earth",new(.32f,.265f,.16f));grass=Mat("Natural moss and grass",new(.22f,.29f,.12f));concrete=Mat("Damp layered concrete",new(.33f,.37f,.35f));wood=Mat("Decaying timber",new(.24f,.17f,.10f));metal=Mat("Storm iron",new(.11f,.14f,.13f));water=Mat("Shallow reflective storm flow",new(.12f,.25f,.27f));gold=Mat("Optional gold",new(1,.7f,.15f));Ridge(old);Physics.SyncTransforms();Drain();TerrainPortals();Trees();Brush();
 if(scene.EndsWith("Reverse")){object P(Vector3 p)=>new{x=p.x,y=p.y,z=p.z};File.WriteAllText(D+"/geometry.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{branches=new[]{ridge,drain}.Select(b=>new{b.title,b.entryRoad,b.exitRoad,b.Length,b.halfWidth,b.aiValidated,b.undergroundStart,b.undergroundEnd,points=b.points.Select(P)}),exit,lip,landing},Newtonsoft.Json.Formatting.Indented));}else{Object.DestroyImmediate(ridge);Object.DestroyImmediate(drain);}EditorSceneManager.MarkSceneDirty(root.gameObject.scene);EditorSceneManager.SaveScene(root.gameObject.scene);AssetDatabase.SaveAssets();notes.Add(scene+" saved");}
 File.WriteAllLines(D+"/authoring.txt",notes);EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");return string.Join("\n",notes);}
 public static string RepairPorts(){serial=800;notes.Clear();Vector3[] dp=null;foreach(string name in new[]{"DansBackyardReverse","DansBackyardForward"}){EditorSceneManager.OpenScene("Assets/Scenes/"+name+".unity");root=GameObject.Find("Reverse optional forest shortcuts").transform;roads=Object.FindObjectsByType<RaceRoad>();drain=root.GetComponentsInChildren<WoodlandRoute>().FirstOrDefault(b=>b.title.StartsWith("Storm"));bool temp=!drain;if(temp){drain=root.gameObject.AddComponent<WoodlandRoute>();drain.points=dp;}else dp=drain.points.ToArray();exit=drain.Project(new(114.3f,0,-66.1f),out _);Physics.SyncTransforms();TerrainPortals();if(temp)Object.DestroyImmediate(drain);
